axiosClient.defaults.adapter=async config=>{const url=new URL(config.url!,'http://fixture.invalid');if(config.method==='put'){writes++;lastBody=String(config.data);lastUrl=url.pathname;if(scenario==='write-slow')await new Promise<void>(resolve=>pending.push(resolve));if(scenario==='write-error')throw Error('Không lưu được đơn kiểm thử.');const body=JSON.parse(String(config.data)),id=Number(url.pathname.split('/')[3]);rows=rows.map(row=>row.id!==id?row:{...row,status:body.shipperId?'Shipping':body.status,shipperId:body.shipperId??row.shipperId});return {data:true,status:200,statusText:'OK',headers:{},config};}
 if(config.method!=='get')throw Error('Unexpected operation');calls++;if(scenario==='slow')await new Promise<void>(resolve=>pending.push(resolve));if(failNext||(scenario==='error'&&calls===1)){failNext=false;throw Error('Không tải được dữ liệu kiểm thử.');}const shippers=url.pathname==='/api/shippers';if(shippers&&scenario==='shipper-error')throw Error('Không tải được nhân viên.');const filter=url.searchParams.get('status'),numeric=['','Pending','Approved','Shipping','Completed','Cancelled'];const data=shippers?(scenario==='no-shippers'?[]:[{id:8,fullName:'Lê Văn Nam'},{id:9,fullName:'Trần Văn Bình'}]):scenario==='malformed'?{}:scenario==='nested-malformed'&&calls===1?[{...rows[0],details:[null]}]:scenario==='empty'?[]:rows.filter(row=>!filter||row.status===filter||numeric[Number(row.status)]===filter);return{data,status:200,statusText:'OK',headers:{},config};};queryClient.setDefaultOptions({queries:{retry:false}});
